module pulse_detect
    (
      input clk, 
      input rst_n, 
      input data_in, 
      output reg data_out
    );

   parameter s0 = 2'd0;
   parameter s1 = 2'd1;
   parameter s2 = 2'd2;
   parameter s3 = 2'd3;

   reg [1:0] pulse_level1;
   reg [1:0] pulse_level2;

   always @(posedge clk or negedge rst_n) begin
      if(!rst_n) begin
        pulse_level1 <= s0;
      end
      else begin
        pulse_level1 <= pulse_level2;
      end
   end

   always @(posedge clk or negedge rst_n) begin
      if(!rst_n) begin
        pulse_level2 <= s0;
      end
      else begin
        case(pulse_level1)
          s0: begin
             if(data_in == 1'b0) begin
               pulse_level2 <= s1;
             end
             else begin
               pulse_level2 <= s0;
             end
          end
          s1: begin
             if(data_in == 1'b1) begin
               pulse_level2 <= s2;
             end
             else begin
               pulse_level2 <= s1;
             end
          end
          s2: begin
             if(data_in == 1'b0) begin
               pulse_level2 <= s3;
             end
             else begin
               pulse_level2 <= s0;
             end
          end
          s3: begin
             if(data_in == 1'b1) begin
               pulse_level2 <= s2;
             end
             else begin
               pulse_level2 <= s1;
             end
          end
        endcase
      end
   end

   assign data_out = (pulse_level2 == s2)? 1'b1:1'b0;

endmodule
